// Port-only (132vt2e, research/VITA.md "Load time"): the level load's phases on the PS Vita, each logged with its
// seconds, the disc reads made in it and the zones (zone_profile.hpp: the load.* decoders among them) it ran, so a
// hardware log shows what the load spends its time on.
// 132vl1 (research/VITA.md "Load time (132vl1)"): with each phase's card reads (vita_io_stats: the sceIoRead calls under
// the disc reads, their bytes and seconds) and, with the test switch vita_test_load_verify.txt, the checks of the load's
// port-only read paths and caches (`verify`: each one compares its bytes with a plain read's; 0 mismatches expected).
struct VitaLoadPhases{
    std::chrono::steady_clock::time_point begun{},last{};
    DiscImage::ReadStats disc{};VitaIoStats io{};
    bool verify=false;std::uint64_t checks=0,mismatches=0;
    static void reset_zones(){for(auto* s=omega::zone::Slot::head().load();s;s=s->next)s->ns=0,s->calls=0,s->allocs=0;}
    void begin(const DiscImage& d){
        verify=vita_file_size(std::string(vita_data_root)+"/vita_test_load_verify.txt")>=0;vita_io_verify(verify);
        begun=last=std::chrono::steady_clock::now();disc=d.read_stats();io=vita_io_stats();reset_zones();
    }
    void check(bool same){++checks;if(!same)++mismatches;}
    void mark(const DiscImage& d,const char* phase){
        const auto now=std::chrono::steady_clock::now();const auto& s=d.read_stats();const auto c=vita_io_stats();
        std::vector<omega::zone::Slot*> slots;
        for(auto* z=omega::zone::Slot::head().load();z;z=z->next)if(z->calls)slots.push_back(z);
        std::sort(slots.begin(),slots.end(),[](auto* a,auto* b){return a->ns>b->ns;});
        char text[1000];
        int n=std::snprintf(text,sizeof text,"Load phase (port-only, PS Vita): %s %.2f s (%.1f s from the hand-off); disc %llu reads, %.2f MB in %.2f s"
            " (card %llu reads, %.2f MB in %.2f s)",
            phase,std::chrono::duration<double>(now-last).count(),std::chrono::duration<double>(now-begun).count(),
            static_cast<unsigned long long>(s.reads-disc.reads),double(s.bytes-disc.bytes)/1048576.0,s.seconds-disc.seconds,
            static_cast<unsigned long long>(c.reads-io.reads),double(c.bytes-io.bytes)/1048576.0,c.seconds-io.seconds);
        if(verify)n+=std::snprintf(text+n,sizeof text-n,"; verify: %llu card reads compared, %llu differ; %llu load checks, %llu differ",
            static_cast<unsigned long long>(c.verified),static_cast<unsigned long long>(c.mismatches),
            static_cast<unsigned long long>(checks),static_cast<unsigned long long>(mismatches));
        for(std::size_t k=0;k<slots.size()&&k<8&&n<int(sizeof text)-90;++k)
            n+=std::snprintf(text+n,sizeof text-n,"%s %s %.0f ms x%u",k?",":"; zones",slots[k]->name,slots[k]->ns/1e6,slots[k]->calls);
        std::cout<<text<<"\n";
        reset_zones();last=std::chrono::steady_clock::now();disc=d.read_stats();io=vita_io_stats();
    }
};
VitaLoadPhases vita_load_phases;
#define VITA_LOAD_PHASE(disc,phase) vita_load_phases.mark(disc,phase)
#else
#define VITA_LOAD_PHASE(disc,phase) do{(void)sizeof(&(disc));}while(false)
#endif

std::string narrow(const std::wstring& text){
    std::string s;
    for(const auto c:text){if(c>127)throw std::runtime_error("Non-ASCII argument");s.push_back(static_cast<char>(c));}
    return s;
}
// Checkpoint 132pw3 (port-only, up to 3 CPU partners): while partner 2's or 3's driver state is swapped in, its log
// lines read "Coop partner 2 ..." / "Coop partner 3 ..." (the first "Coop partner" of each line is tagged).
class CoopLogTag:public std::streambuf{
public:
    CoopLogTag()=default;
    CoopLogTag(const CoopLogTag&)=delete;
    CoopLogTag& operator=(const CoopLogTag&)=delete;
    ~CoopLogTag() override{end();}
    void begin(std::size_t partner){
        if(previous_)throw std::logic_error("Coop partner log tag: already tagging");
        tag_="Coop partner "+std::to_string(partner);
        previous_=std::cout.rdbuf(this);
    }
    void end(){
        if(!previous_)return;
        flush_line();
        std::cout.rdbuf(previous_);
        previous_=nullptr;
    }
protected:
    int_type overflow(int_type c) override{
        if(traits_type::eq_int_type(c,traits_type::eof()))return traits_type::not_eof(c);
        line_.push_back(traits_type::to_char_type(c));
        if(line_.back()=='\n')flush_line();
        return c;
    }
    std::streamsize xsputn(const char* s,std::streamsize n) override{
        for(std::streamsize i=0;i<n;++i)overflow(traits_type::to_int_type(s[i]));
        return n;
    }
    int sync() override{return previous_?previous_->pubsync():0;}
private:
    void flush_line(){
        if(line_.empty()||!previous_)return;
        constexpr std::string_view untagged="Coop partner";
        if(const auto at=line_.find(untagged);at!=std::string::npos
           &&(at+untagged.size()==line_.size()||line_[at+untagged.size()]==' '||line_[at+untagged.size()]==':'))
            line_.replace(at,untagged.size(),tag_);
        previous_->sputn(line_.data(),static_cast<std::streamsize>(line_.size()));
        line_.clear();
    }
    std::streambuf* previous_{};
    std::string tag_,line_;
};
// Swaps partner k's driver state in for its lifetime (play's coop_swap).
template<class F>class CoopPartnerScope{
public:
    CoopPartnerScope(const F& swap,std::size_t k):swap_(swap),k_(k){swap_(k_,true);}
    ~CoopPartnerScope(){swap_(k_,false);}
    CoopPartnerScope(const CoopPartnerScope&)=delete;
    CoopPartnerScope& operator=(const CoopPartnerScope&)=delete;
private:
    const F& swap_;
    std::size_t k_;
};
template<class T>T number(const std::wstring& text){
    const auto s=narrow(text);T value{};
    auto r=std::from_chars(s.data(),s.data()+s.size(),value);
    if(r.ec!=std::errc{}||r.ptr!=s.data()+s.size())throw std::runtime_error("Invalid number: "+s);
    return value;
}
void local_path(const fs::path& path){
    const auto root=fs::absolute("local").lexically_normal(),full=fs::absolute(path).lexically_normal();
    const auto relative=full.lexically_relative(root);
    if(relative.empty()||relative.is_absolute()||*relative.begin()==".."||full==root)
        throw std::runtime_error("Sandbox data and output must stay under local");
}
std::span<const std::uint8_t> nested(std::span<const std::uint8_t> archive,const std::string& name){
    const auto extent=hog_member(archive,archive.size(),name);
    return checked_bytes(archive,static_cast<std::size_t>(extent.offset),static_cast<std::size_t>(extent.size));
}
std::string hex_word(std::uint32_t v){std::ostringstream s;s<<std::hex<<v;return s.str();}
// A TDX member as its GS upload reads it (tdx_in_place). The level load opens the mission NPCTEX.HOG in memory
// (001457c0 -> Archive_Open 003f96e0, a2 0 -> Hog_Load 0036cef0 type 1) and 00403d20 reads and relocates every
// member in place, so a member cut short (_BEAR_MOU_BLAC0) continues into the next member's header, +0x3c set.
std::vector<std::uint8_t> tdx_member(DiscImage& disc,const std::vector<std::string>& archive,const std::string& member){
    auto bytes=disc.archive_member(archive,member);
    if(archive.empty()||archive.back()!="NPCTEX.HOG"||bytes.size()<64)return bytes;
    const auto u32=[&](std::size_t at){return std::uint32_t(bytes[at])|bytes[at+1]<<8|bytes[at+2]<<16|std::uint32_t(bytes[at+3])<<24;};
    const auto upload=64+std::uint64_t(bytes[34]|bytes[35]<<8)*u32(56);
    if(upload<=bytes.size())return bytes;
    const auto container=disc.file(archive);const auto extent=disc.archive_member_extent(archive,member);
    const auto image=disc.read({extent.offset,std::min(upload,container.offset+container.size-extent.offset)});
    std::vector<std::size_t> relocated;
    for(const auto& name:disc.archive_member_names(archive))
        if(name.size()>4&&name.compare(name.size()-4,4,".TDX")==0)
            if(const auto at=disc.archive_member_extent(archive,name).offset;at>extent.offset&&at-extent.offset<image.size())
                relocated.push_back(static_cast<std::size_t>(at-extent.offset));
    return tdx_in_place(image,0,bytes.size(),relocated);
}

// AnimatedCharacter as the simulation's animation model.
struct CharacterAnimation final:SoloActorAnimation {
    AnimatedCharacter& character;const AnimationGraphManifest& manifest;const AnimationGraph& graph;const AnimationClipBank& clips;MorphHostInput morph;
    const ActorMotionRegistry& registry;ActorMotionRegistration retained;
    // retained: actor +326c, the node 001ae7d0 saves for the started motion (CoreMotions).
    // registry: the one model's (*0x4ffbd8) map, shared by every character; game::LoadAnimation appends to it.
    CharacterAnimation(AnimatedCharacter& c,const AnimationGraphManifest& m,const AnimationClipBank& b,const ActorMotionRegistry& r,std::string_view motion)
        :character(c),manifest(m),graph(m.graph),clips(b),registry(r),retained(actor_motion_registration(m.root(motion))){
        morph.expressions_enabled=false;
    }
    ActorMotionRegistration resolve_motion(std::string_view name) const override{
        ActorMotionSelection selection;selection.tag=0;selection.name=std::string(name);
        return registry.resolve(selection);
    }
    // Model +0x44 (001926d0): the manifest's named roots; an absent name throws.
    ActorMotionRegistration resolve_named_root(std::string_view name) const override{
        return actor_motion_registration(manifest.root(name));
    }
    // Model +0x24 (0018c740): node index by node name; nullopt when absent.
    std::optional<std::uint32_t> motion_node_id(std::string_view name) const override{
        const auto& nodes=graph.nodes();
        for(std::size_t i=0;i<nodes.size();++i)if(nodes[i].name==name)return static_cast<std::uint32_t>(i);
        return std::nullopt;
    }
    // 0018a420 tag 1: the numeric node id.
    ActorMotionRegistration resolve_motion_id(std::uint32_t id) const override{
        ActorMotionSelection selection;selection.tag=1;selection.numeric_id=id;
        return registry.resolve(selection);
    }
    ActorMotionRegistration retained_motion() const override{return retained;}
    // 0018a410: the model's default transition duration.
    std::optional<float> default_motion_duration() const override{return manifest.default_crossfade_duration;}
    // 001901c0 through the graph and clips (001a2470, DATA_ID_JumpGrabLedge).
    std::optional<RootParentTransform> motion_start_placement(std::string_view motion_name) const override{
        return resolve_receiver_motion_placement(graph,clips,motion_name,{},MotionPlacementEndpoint::start);}
    std::optional<RootParentTransform> motion_end_placement(std::string_view motion_name) const override{
        return resolve_receiver_motion_placement(graph,clips,motion_name,{},MotionPlacementEndpoint::end);}
    std::optional<RootAnchorKey> motion_anchor_key(std::string_view name) const override{
        const AnimationGraphNode* selected=nullptr;
        for(const auto& node:graph.nodes())if(node.name==name){
            if(selected)throw std::runtime_error("Ambiguous actor motion registry key");
            selected=&node;
        }
        if(!selected)throw std::runtime_error("Motion anchor key of an unknown motion (0018c5a0 index-0 fallback): "+std::string(name));
        return leaf_anchor_key(*selected);
    }
    // 0018c6b0 *(model+3c)[id]: the node index (unchecked in the original).
    std::optional<RootAnchorKey> motion_anchor_key_by_id(std::uint32_t id) const override{
        const auto& nodes=graph.nodes();
        if(id>=nodes.size())throw std::runtime_error("Motion anchor key: node id outside the model (0018c6b0 unchecked read)");
        return leaf_anchor_key(nodes[id]);
    }
    // 001914a0 (byte +4 == 0: a leaf) and the leaf clip header word +24.
    std::optional<RootAnchorKey> leaf_anchor_key(const AnimationGraphNode& node) const{
        if(node.kind!=AnimationGraphKind::Leaf)return std::nullopt;
        const auto at=clips.find(node.leaf.clip_key);
        if(at==clips.end())throw std::runtime_error("Motion anchor key: clip is unresolved");
        const auto& h=at->second.header_bytes;
        return RootAnchorKey{h[0x24],h[0x25],h[0x26],h[0x27]};
    }
    void install_motion(const MotionRequest& r,MotionInstallMode m) override{character.play(r,m);}
    void set_motion_sink(MotionDeliveryHooks::Sink sink) override{
        MotionDeliveryHooks hooks;hooks.immediate=std::move(sink);
        hooks.enqueue=[](const MotionEffect&,const MotionDeliveryView&){
            throw std::runtime_error("Queued animation effects are not hosted by the sandbox");
        };
        character.set_delivery_hooks(std::move(hooks));
    }
    std::size_t channel_count() const override{return character.model().channel_count();}
    const AnimationChannelState& channel(std::size_t i) const override{return character.model().channel(i);}
    void apply_commands(std::span<const ActorChannelCommand> c) override{character.apply_commands(c);}
    void set_anchor_world_orientation(const RootAnchorKey& k,const RootVector& q,bool reset) override{character.set_anchor_world_orientation(k,q,reset);}
    void set_anchor_world_position(const RootAnchorKey& k,const RootVector& v) override{character.set_anchor_world_position(k,v);}
    void set_anchor_world_placement(const RootAnchorKey& k,const RootParentTransform& t,bool reset) override{character.set_anchor_world_placement(k,t,reset);}
    void set_anchor_state(const RootAnchorKey& k,const RootAnimationState& s) override{character.set_anchor_state(k,s);}
    void set_anchor_parent(const RootAnchorKey& k,std::optional<RootParentTransform> p) override{character.set_anchor_parent(k,std::move(p));}
    void set_anchor_constraint(const RootAnchorKey& k,std::optional<RootMotionConstraint> c) override{character.set_anchor_constraint(k,c);}
    // 003915b0's clock (play's speech_clock_ms); null: the frame count.
    const std::int32_t* speech_clock{};
    // Port-only report of each lip-sync stream: its steps, peak face-slot count and weight, logged when 003915b0 ends it.
    std::size_t speech_steps{};std::uint8_t speech_peak_slots{};float speech_peak_weight{};
    // 132cp11: the actor fields 00389fa0 / 0038b530 read and write around the morph step (the
    // draw mode +2bda gate, the EMO_SHOT counter +2d92, the grip counters +2d90/+2d91, the
    // equipment +2410/+2414 and the RNG of a periodic reset), synced in before and out after.
    std::function<void(MorphHostState&,MorphHostInput&,AnimatedCharacterResourceInput&)> morph_prepare;
    std::function<void(const MorphHostState&)> morph_commit;
    void step(float dt) override{
        if(speech_clock)morph.speech_clock=*speech_clock;
        const bool speaking=character.morph().speech_active;
        AnimatedCharacterResourceInput resources;
        if(morph_prepare){auto state=character.morph();morph_prepare(state,morph,resources);character.set_morph_state(state);}
        character.step(graph,clips,{},morph,dt,{},resources);++morph.speech_elapsed_tick;
        if(morph_commit)morph_commit(character.morph());
        if(!speaking)return;
        const auto& m=character.morph();++speech_steps;speech_peak_slots=std::max(speech_peak_slots,m.active_count);
        for(std::size_t i=0;i<m.active_count&&i<m.face_slots.size();++i)speech_peak_weight=std::max(speech_peak_weight,m.face_slots[i].weight);
        if(m.speech_active)return;
        std::cout<<"Lip sync ended (003915b0 cleared +2d68) at "<<(speech_clock?*speech_clock:0)<<" ms after "<<speech_steps
                 <<" steps: up to "<<int(speech_peak_slots)<<" face slots, peak weight "<<speech_peak_weight<<"\n";
        speech_steps=0;speech_peak_slots=0;speech_peak_weight=0;}
    RootAnimationState anchor_state(const RootAnchorKey& k) const override{
        for(const auto& anchor:character.model().player().anchors)if(anchor.key==k)return anchor.state;
        throw std::runtime_error("Character has no such root anchor");
    }
    // Root +d0: the anchor weight accumulated by the last model evaluation.
    std::optional<float> anchor_weight(const RootAnchorKey& k) const override{
        for(const auto& anchor:character.model().player().anchors)if(anchor.key==k)return anchor.weight;
        return std::nullopt;
    }
    bool has_anchor(const RootAnchorKey& k) const override{
        for(const auto& anchor:character.model().player().anchors)if(anchor.key==k)return true;
        return false;
    }
    // 003ab510 publishes the pose aggregate (model +c0/+d0) into the model's
    // transform component (context +28).
    std::optional<RootParentTransform> published_placement() const override{
        const auto& player=character.model().player();
        return RootParentTransform{player.orientation,player.position};
    }
    // 00132910: the node's skeleton-space translation (player.world, file
    // order) through that published component.
    RootVector skeleton_node_world_position(int node) const override{
        const auto& player=character.model().player();
        return published_skeleton_node_position({player.orientation,player.position},player.world,node);
    }
    // 00133ed0: every row of the node's matrix through the same published component (the perception's head node 14).
    std::array<RootVector,4> skeleton_node_world_matrix(int node) const override{
        const auto& player=character.model().player();
        return published_skeleton_node_matrix({player.orientation,player.position},player.world,node);
    }
    // 003a9220 / 0038a7c0: the skeleton-space node matrices (player.world, file order).
    std::span<const std::array<float,16>> skeleton_node_matrices() const override{return character.model().player().world;}
    // The skeleton's node collection (context +14): centroid weights and context +50.
    bool human_node_collection() const override{return true;}
    // Model +e0/+f0 (003ae750's base aggregate) and node 0 +1a0 for the upper-body aim (secondary_aim.hpp).
    RootParentTransform base_aggregate() const override{
        const auto& player=character.model().player();
        return RootParentTransform{player.base_orientation,player.base_position};
    }
    RootVector bone0_rotation() const override{return character.model().player().bone0_rotation;}
    // Node +1a0: node 0's rotation finalizer cache (003ba2b0), the pose
    // bones' rotation caches; +1b0: node 0's translation row, the pose bones'
    // translation caches; the bone record +8..+10 is the skeleton's local
    // offset and the parent byte its parent (none: 0xff).
    UpperBodyModelNodes upper_body_nodes() const override{
        const auto& sk=character.skeleton();const auto& p=character.model().player();
        if(sk.bones.size()<upper_body_entry_count||p.pose.bones.size()+1!=sk.bones.size())
            throw std::runtime_error("The upper-body pass needs a skeleton of at least 21 nodes");
        UpperBodyModelNodes m;m.bone_count=static_cast<std::uint32_t>(sk.bones.size());
        for(std::size_t k=0;k<upper_body_entry_count;++k){
            const auto& b=sk.bones[k];
            m.parent_bytes[k]=b.parent<0?std::uint8_t{0xff}:static_cast<std::uint8_t>(b.parent);
            auto& n=m.nodes[k];
            n.bone_offset={b.local_offset.x,b.local_offset.y,b.local_offset.z};
            if(k==0){n.pose=p.bone0_rotation;n.offset={p.root_local[12],p.root_local[13],p.root_local[14],1.0F};}
            else{n.pose=p.pose.bones[k-1].rotation_cache;n.offset=p.pose.bones[k-1].translation_cache;}
            const auto& local=k?p.pose.bones[k-1].local:p.root_local;   // node +90 (001cf3f0)
            m.translation_90[k]={local[12],local[13],local[14],local[15]};
        }
        return m;
    }
    void write_upper_body_nodes(std::span<const std::optional<std::array<float,12>>> rows,const std::optional<RootVector>& root_translation) override{
        character.write_node_locals(rows,root_translation);
    }
    // 00198f30 / 00198ca0 / 001987d0 on the model's controller and player (actor +2ec0).
    std::optional<ActorGaitSample> gait_sample(std::int32_t group) const override{
        return actor_gait_sample(character.model().controller(),character.model().player(),graph,group);
    }
};

// Scripted input: "frames x y p10 p11 [rx ry]" per line (physical deflection,
// up +Y; rx/ry is the right stick for the camera look offset; then optional
// Cross and Triangle, then optional Square and R1 for --combat, then optional L1, then optional Circle,
// then optional D-pad Up, Down, Left and Right, all four together),
// then optional PAD: a raw pad 0 mask (C notation, e.g. 0x800 Start) ORed into the held buttons the pad
// driver reads (the in-game start menu, checkpoint 132f; needs --gui-overlay).
// A line "teleport X Y Z YAW" (host test convenience, not game behaviour) places the
// local player there before the next frame through the game's own Teleport Message
// (001bc4b0, mode 2), as the checkpoint revive does; YAW in degrees as --start.
// A line "waitpeer" (132ln5h12, LAN test convenience) gives no input until the other console's human is in
// the level (LanNetCore created its remote human), so two consoles' scripts line up whenever the joiner arrives.
// 132ln5h14 (LAN test conveniences): "waitleft" gives no input until that human has left again (its client quit);
// "quit" ends the play there, as --frames does (a host that outlives its joiner stops before its NPCs kill it).
struct ScriptStep{unsigned frames{};float x{},y{},p10{},p11{},rx{},ry{},cross{},triangle{},square{},r1{},l1{},circle{};
    std::array<float,4> dpad{};   // Up, Down, Left, Right (sp+fb0..fbc)
    std::uint32_t pad{};          // the PAD column (checkpoint 132f)
    std::optional<std::array<float,4>> teleport;
    std::optional<float> rise;    // 132ws9 "rise H" (port-only soak aid, tools\run_soak.ps1): the test teleport H above the player
    bool wait_peer{},wait_left{},quit{};};
// --dt-trace: one world dt per frame as the IEEE-754 bits in hex (for example
// 3d08a4b2, as read from the emulator's 005383d0), '#' comments allowed.
std::vector<float> read_dt_trace(const fs::path& path){
    std::ifstream in(path);if(!in)throw std::runtime_error("Cannot read dt trace");
    std::vector<float> out;std::string line;
    while(std::getline(in,line)){
        if(!line.empty()&&line.back()=='\r')line.pop_back();
        if(line.empty()||line[0]=='#')continue;
        std::size_t used=0;const auto bits=std::stoul(line,&used,16);
        if(used!=line.size()||bits>0xffffffffUL)throw std::runtime_error("Invalid dt trace line: "+line);
        const float v=std::bit_cast<float>(static_cast<std::uint32_t>(bits));
        if(!(v>0.0F)||!std::isfinite(v))throw std::runtime_error("dt trace values must be positive: "+line);
        out.push_back(v);
    }
    if(out.empty())throw std::runtime_error("Empty dt trace");
    return out;
}
std::vector<ScriptStep> read_script(const fs::path& path){
    std::ifstream in(path);if(!in)throw std::runtime_error("Cannot read input script");
    std::vector<ScriptStep> steps;std::string line;
    while(std::getline(in,line)){
        if(!line.empty()&&line.back()=='\r')line.pop_back();
        if(line.empty()||line[0]=='#')continue;
        std::istringstream fields(line);ScriptStep s;
        if(line.rfind("teleport",0)==0){
            std::string op;std::array<float,4> v{};fields>>op;
            for(auto& value:v)if(!(fields>>value))throw std::runtime_error("Script teleport needs X Y Z YAW: "+line);
            s.teleport=v;steps.push_back(s);continue;
        }
        if(line.rfind("rise ",0)==0){
            std::string op;float h=0;fields>>op;
            if(!(fields>>h)||!std::isfinite(h))throw std::runtime_error("Script rise needs a height: "+line);
            s.rise=h;steps.push_back(s);continue;
        }
        if(line=="waitpeer"){s.wait_peer=true;steps.push_back(s);continue;}
        if(line=="waitleft"){s.wait_left=true;steps.push_back(s);continue;}
        if(line=="quit"){s.quit=true;steps.push_back(s);continue;}
        if(!(fields>>s.frames>>s.x>>s.y>>s.p10>>s.p11)||s.frames>100000)throw std::runtime_error("Invalid input script line: "+line);
        if(fields>>s.rx){if(!(fields>>s.ry))throw std::runtime_error("Script right stick needs two values: "+line);
            if(fields>>s.cross){if(!(fields>>s.triangle))throw std::runtime_error("Script buttons need Cross and Triangle: "+line);
                if(fields>>s.square){if(!(fields>>s.r1))throw std::runtime_error("Script combat buttons need Square and R1: "+line);
                    if(fields>>s.l1){if(fields>>s.circle){
                        if(fields>>s.dpad[0]){if(!(fields>>s.dpad[1]>>s.dpad[2]>>s.dpad[3]))
                            throw std::runtime_error("Script D-pad needs Up, Down, Left and Right: "+line);
                            std::string mask;if(fields>>mask){std::size_t used=0;const auto v=std::stoul(mask,&used,0);
                                if(used!=mask.size()||v>0xffffUL)throw std::runtime_error("Script pad mask: "+line);s.pad=static_cast<std::uint32_t>(v);}}}}}}}
        steps.push_back(s);
    }
    return steps;
}

// --pilot (route authoring aid, not a game feature): after the --script prefix ends, closed-loop
// commands produce the pad input from the player's floor root, and --record writes every frame's
// input (and every teleport, the prefix's included) as a plain play script, which replays the same run
// without the pilot. Commands:
//   goto X Y [tolerance] [max_frames] [window]   turn toward (X, Y), walk until within tolerance (default 0.6)
//                                       or until a near pass starts to recede; a standing player starts
//                                       walking once the heading error is under window degrees (default 5;
//                                       carrying a body, the in-place turn steps are coarse: use about 25)
//   face H [tolerance]                  settle, then turn in place to heading H (degrees; direction
//                                       (-sin H, cos H)), within tolerance (default 8)
//   aimat N tolerance gain X Y Z        N frames in the aim view (L1) turned onto the point (X, Y, Z) as
//                                       aim does; Square for 2 frames when within tolerance, 28 apart.
//                                       A negative tolerance fires only on a frame whose aim-view probe
//                                       raised the headshot popup (00249c78: category 2, live object)
//   seek X Y MASK [N]                   walk toward (X, Y) until the found-ledge prompt has a bit of
//                                       MASK (decimal), then Triangle for N frames (default 1)
//   hold N x y p10 p11 rx ry cross triangle square r1 l1 [circle [up down left right [select]]]   raw input for N frames
//   wait N                              no input for N frames
//   waitcommand N                       (checkpoint 132pc1) no input until the CPU partner's command (coop_partner.hpp
//                                       CoopCommandRule) reports its action over, at most N frames
//   waitactive N ID                     (checkpoint 132ms4) no input until the NPC ID is present (activated by its
//                                       script), at most N frames
//   teleport X Y Z YAW                  the script "teleport" line (host test convenience); recorded as such
//   aim N TOLERANCE GAIN ID [ID...]     hold L1 (the manual aim view) for up to N frames, steer the right
//                                       stick (GAIN per degree) so the camera +50 forward row (row 1)
//                                       points at the head (eye node 14, 00188d80 subtarget 0) of the
//                                       nearest living listed --combat actor, and press Square on
//                                       alternate frames while both errors are within TOLERANCE degrees;
//                                       with one ID, done early once that actor's life state is 2 or 3;
//                                       with several, done early once every listed ID has been seen dead
//                                       (a spawned corpse, in this command or an earlier one); IDs are
//                                       read exactly (as doubles: spawn IDs exceed 2^24);
//                                       a negative ID -K names a friendly K: Square is held back while
//                                       its head is within 2 units of the line of fire; a negative
//                                       TOLERANCE fires only on headshot-popup frames, the stick leading by
//                                       the error's rate (as aimat) and starting past the pad's dead zone
//   hunt N TOLERANCE GAIN RANGE ID [ID...]   as aim, but while the target is farther than RANGE
//                                       (horizontal distance) release L1 and walk toward it (the aim
//                                       view does not walk); in range, aim as above. In both commands
//                                       L1 is re-pressed (3 frames released) when the pitch error stays
//                                       above 15 degrees for 45 frames (the view has left aim mode).
//                                       (Checkpoint 132ms3) TOLERANCE 0 fires with the R1 lock-on as clear does
//                                       (hunt only once in RANGE): no aim view, so no aim-view pitch limit. R1 is
//                                       held only while the body faces the target (25 degrees, 60 once held; the
//                                       body turns in place otherwise), and a lock on a living listed target is
//                                       followed instead of the nearest one (R1 then stays held and Square fires at it,
//                                       whatever the body's heading)
//   pickup RADIUS [BUDGET]               walk to the nearest dropped (dead NPC) backpack within RADIUS that
//                                       no pickup has reached yet, until within 1 unit (inside its hotbox,
//                                       where the walk-over 00254da0 runs); done when none is left, or
//                                       after BUDGET frames (default 600) without a stop
//   clear N TOLERANCE GAIN RADIUS [-ID...]   (checkpoint 132uk6) as aim (TOLERANCE 0: R1 lock-on fire instead, the body
//                                       turning to face the target, Square every 8 frames) at every living spawned
//                                       actor other than the player within RADIUS (horizontal; height within 30), in
//                                       the player's line of sight (head to head, the bullet's static world LOS) and
//                                       not listed as a friendly (-ID), nearest first. A target more than 30 degrees
//                                       off the body's heading is turned to with the body (faster than the aim view);
//                                       the fire tolerance is TOLERANCE capped at 1 unit off the head at the target's
//                                       range (at least half a unit). A target that took no damage from 20 presses is
//                                       passed over until the player has moved 15 units or the target 4 (out of its
//                                       cover); done when none is left, or after N frames
//   waitnear N ID X Y R                  (checkpoint 132uk6) wait until actor ID is within R (horizontal) of
//                                       (X, Y); the run stops after N frames
//   stalk N RANGE ID [STICK]            (checkpoint 132ms1) walk toward the --combat actor ID (stick forward
//                                       scaled by STICK, default 1) and, within RANGE (horizontal), press Square
//                                       for 2 frames every 12 (the melee trigger; from behind with a knife it is
//                                       the takedown); done once its life state is 2 or 3, stops the run after N
//   waitnpc N ID X0 Y0 X1 Y1            (checkpoint 132ms1) stand still until the --combat actor ID is inside the
//                                       horizontal rectangle X0..X1 by Y0..Y1 (to pass a patrol behind its back);
//                                       stops the run after N frames
//   strike N RANGE ID [PRESSES]           (checkpoint 132ms2) walk toward the --combat actor ID until within RANGE
//                                       (horizontal), turn the body onto it and press Square (no L1: the held melee
//                                       item's swing) for 2 frames, 30 apart; done PRESSES (default 1) presses and
//                                       30 frames later, when the actor is dead, or after N frames
//   waitbeam N ID HEIGHT                 (checkpoint 132ms2) wait until the kind-6 beam NIE ID (its world segment, as
//                                       0023a6f4 places it) passes at least HEIGHT above the player's feet at the
//                                       player's horizontal position, having been below it the frame before (an
//                                       upward crossing, so a wait begun near the top waits a cycle): a sweeping laser's crossing,
//                                       timed as a player watches it; the run stops after N frames
//   waitbeamrise N ID HEIGHT             (checkpoint 132ms2) as waitbeam, but done as soon as the beam is at least
//                                       HEIGHT above the feet and still rising (no crossing needed, so a wait begun
//                                       just after the crossing goes at once)
//   waitbeamoff N ID                     (checkpoint 132ms2) wait until the blinking beam NIE ID switches off (its
//                                       switch +dc on in the previous frame, off now); the run stops after N frames
//   waitbeamend N ID X Y R               (checkpoint 132ms2) wait until the beam NIE ID's start point (a swinging
//                                       laser's free end) comes within R of (X, Y) horizontally while approaching it
//                                       (closer than the previous frame); the run stops after N frames
//   hold's optional 18th value presses Select (checkpoint 132uk6).
//   npcwatch R PERIOD                   (checkpoint 132ms8d) from now on, every PERIOD frames (0: off), print each
//                                       present --combat actor within R (horizontal) with its position, floor-root heading
//                                       (degrees, as the player's) and life state (takes no frame)
//   goto prints the player's position every 120 frames ("Pilot goto at frame").
//   In aim and hunt an ID may be gG: every actor generator G has spawned (spawn IDs depend on the
//   run's spawn order, and IDs above 2^24 are not exact as floats); a lone gG is done early once G
//   has spawned and none of its spawns is alive.
//   (Checkpoint 132ob11) An aim or hunt token cK (K > 0) passes over a target behind cover: one whose
//   health and armor did not change over K Square presses in tolerance is skipped for the nearest
//   other living listed target (and aimed at again when no other is left). Without cK every target
//   is kept until it dies.
//   (Checkpoint 132uk6e) An aim or hunt token uF aims F units above the head node (14), and sN
//   spaces the Square presses at least N frames apart (single shots whose recoil has settled).
//   (Checkpoint 132ms6) An aim or hunt token hK (K >= 0) holds still K frames after a kill with the R1
//   lock-on instead of 300 (h0: none; for waves whose spawns schedule no call on their AI). A token d
//   with listed IDs and gG ends the command once every listed ID is dead (the gG spawns are only
//   shot meanwhile, nearest first); with gG only (one or more), once any listed generator has spawned and
//   none of their spawns is alive (a straggler sweep between scripted targets). A token l fires only with
//   the lock's aim meter full (no unlocked shot at a target within 30 units: it goes the body's way level,
//   and a scoped weapon's rounds are scarce); lN (N > 0) does so only for a target N units away or more: a
//   nearer one (a straggler closing in, whose angular speed keeps the meter low) is fired at once locked,
//   or unlocked as without l. A token rN (N > 0) leaves out a gG spawn more than N units away (level), as
//   if not alive (turning the body to a far one walks it off its spot). A token v presses unlocked only at
//   a target within 3 units of the player's floor (not one on a ladder or the ground below a balcony, which
//   the level shot misses; an NPC's published position stands about 3.2 units above the player's on the
//   same floor). A token a (anchor) keeps the player on the spot the command started at: turning in place
//   to a target far off moves the body (behind a pillar, out of the lock's sight), so away more than 0.8
//   units without a lock held, the player walks back (to 0.3) before turning or firing again. It suits a
//   target in front (one at the player's back keeps the turn stepping the body off the spot: leave a out
//   there); a target within 30 units (the unlocked shot's range) is fought where the player stands.
//   A token tID (till) ends the command once the NPC ID is present (activated by its script, as waitactive),
//   so a wave's sweep hands over to a scripted target the wave's end brings on while the generators still
//   spawn. A token pN (N > 0, near first) makes the nearest listed target in the player's sight within N
//   units win over the R1 lock already held on another (a straggler closing in from behind while a far one
//   is locked).
// A goto, face or seek that runs past its frame budget stops the run with a message.
struct PilotCommand{std::string op;std::vector<float> args;std::vector<double> wide;std::string text;std::vector<std::uint32_t> generators;unsigned cover=0;float up=0;unsigned spacing=0;
    unsigned kill_hold=300;bool ids_done=false;bool lock_only=false;bool level_only=false;float generator_range=0;bool anchor=false;double until_active=0;float near_first=0;float lock_close=0;};   // wide: exact actor IDs (above 2^24)
std::vector<PilotCommand> read_pilot(const fs::path& path){
    std::ifstream in(path);if(!in)throw std::runtime_error("Cannot read pilot file");
    std::vector<PilotCommand> out;std::string line;
    while(std::getline(in,line)){
        if(!line.empty()&&line.back()=='\r')line.pop_back();
        if(line.empty()||line[0]=='#')continue;
        std::istringstream f(line);PilotCommand c;c.text=line;f>>c.op;std::string token;
        while(f>>token){
            std::size_t used=0;
            try{
                if(token=="d"){c.ids_done=true;used=1;}
                else if(token=="l"){c.lock_only=true;used=1;}
                else if(token=="v"){c.level_only=true;used=1;}
                else if(token=="a"){c.anchor=true;used=1;}
                else if(token.size()>1&&token[0]=='l'){c.lock_only=true;c.lock_close=static_cast<float>(std::stod(token.substr(1),&used));++used;if(c.lock_close<=0)used=0;}
                else if(token.size()>1&&token[0]=='t'){c.until_active=std::stod(token.substr(1),&used);++used;if(c.until_active<=0)used=0;}
                else if(token.size()>1&&token[0]=='p'){c.near_first=static_cast<float>(std::stod(token.substr(1),&used));++used;if(c.near_first<=0)used=0;}
                else if(token.size()>1&&token[0]=='r'){c.generator_range=static_cast<float>(std::stod(token.substr(1),&used));++used;if(c.generator_range<=0)used=0;}
                else if(token.size()>1&&token[0]=='h'){c.kill_hold=static_cast<unsigned>(std::stoul(token.substr(1),&used));++used;}
                else if(token.size()>1&&token[0]=='g'){const auto g=std::stoul(token.substr(1),&used);++used;c.generators.push_back(static_cast<std::uint32_t>(g));}
                else if(token.size()>1&&token[0]=='c'){c.cover=static_cast<unsigned>(std::stoul(token.substr(1),&used));++used;if(c.cover==0)used=0;}
                else if(token.size()>1&&token[0]=='u'){c.up=std::stof(token.substr(1),&used);++used;}
                else if(token.size()>1&&token[0]=='s'){c.spacing=static_cast<unsigned>(std::stoul(token.substr(1),&used));++used;if(c.spacing==0)used=0;}
                else{const double v=std::stod(token,&used);c.args.push_back(static_cast<float>(v));c.wide.push_back(v);}
            }catch(const std::exception&){used=0;}
            if(used!=token.size())throw std::runtime_error("Pilot command arguments: "+line);
        }
        if((!c.generators.empty()||c.cover||c.up!=0||c.spacing||c.kill_hold!=300||c.ids_done||c.lock_only||c.level_only||c.anchor||c.generator_range>0||c.until_active>0||c.near_first>0)&&c.op!="aim"&&c.op!="hunt")throw std::runtime_error("Pilot command arguments: "+line);
        if(c.op!="goto"&&c.op!="face"&&c.op!="hold"&&c.op!="wait"&&c.op!="seek"&&c.op!="teleport"&&c.op!="aim"&&c.op!="hunt"&&c.op!="aimat"&&c.op!="pickup"&&c.op!="waitcommand"&&c.op!="waitactive"&&c.op!="clear"&&c.op!="waitnear"&&c.op!="stalk"&&c.op!="waitnpc"&&c.op!="npcwatch"&&c.op!="strike"&&c.op!="waitbeam"&&c.op!="waitbeamrise"&&c.op!="waitbeamoff"&&c.op!="waitbeamend")throw std::runtime_error("Unknown pilot command: "+line);
        if(c.op=="clear"){c.cover=20;if(c.args.size()<4||std::any_of(c.args.begin()+4,c.args.end(),[](float v){return v>=0;}))throw std::runtime_error("Pilot command arguments: "+line);}
        if((c.op=="goto"&&c.args.size()<2)||(c.op=="aim"&&c.args.size()+c.generators.size()<4)||(c.op=="hunt"&&c.args.size()+c.generators.size()<5)||(c.op=="aimat"&&c.args.size()!=6)||(c.op=="waitnear"&&c.args.size()!=5)||((c.op=="waitbeam"||c.op=="waitbeamrise")&&c.args.size()!=3)||(c.op=="waitbeamoff"&&c.args.size()!=2)||(c.op=="waitbeamend"&&c.args.size()!=5)||(c.op=="face"&&c.args.size()<1)||(c.op=="hold"&&c.args.size()!=12&&c.args.size()!=13&&c.args.size()!=17&&c.args.size()!=18)||((c.op=="wait"||c.op=="waitcommand")&&c.args.size()!=1)||(c.op=="waitactive"&&c.args.size()!=2)||
            (c.op=="seek"&&c.args.size()<3)||(c.op=="teleport"&&c.args.size()!=4)||(c.op=="pickup"&&c.args.empty())||(c.op=="stalk"&&c.args.size()!=3&&c.args.size()!=4)||(c.op=="waitnpc"&&c.args.size()!=6)||(c.op=="npcwatch"&&(c.args.size()!=2||c.args[1]<0))||(c.op=="strike"&&c.args.size()!=3&&c.args.size()!=4))
            throw std::runtime_error("Pilot command arguments: "+line);
        out.push_back(std::move(c));
    }
    return out;
}
// The value the recorded script will parse back (2 decimals), so a replay sees identical floats.
float pilot_quantize(float v){char buffer[32];std::snprintf(buffer,sizeof buffer,"%.2f",double(v));std::istringstream in(buffer);float out=0;in>>out;return out;}
struct PilotRecorder{
    std::ofstream out;std::string row;unsigned count=0;
    void add(const std::array<float,18>& v){
        char buffer[200];std::snprintf(buffer,sizeof buffer,"%.2f %.2f %.2f %.2f %.2f %.2f %.2f %.2f %.2f %.2f %.2f",
            double(v[1]),double(v[2]),double(v[3]),double(v[4]),double(v[5]),double(v[6]),double(v[7]),double(v[8]),double(v[9]),double(v[10]),double(v[11]));
        // Circle as a 13th column only when it or the D-pad is pressed, the D-pad (14th..17th) only when
        // pressed, so recordings without them are unchanged. (Checkpoint 132ms4) Select as the script's PAD
        // column 0x100 (18th), with Circle and the D-pad written before it.
        const bool select=v[17]!=0.0F;
        const bool dpad=v[13]!=0.0F||v[14]!=0.0F||v[15]!=0.0F||v[16]!=0.0F||select;
        if(v[12]!=0.0F||dpad){const auto n=std::strlen(buffer);std::snprintf(buffer+n,sizeof buffer-n," %.2f",double(v[12]));}
        if(dpad){const auto n=std::strlen(buffer);
            std::snprintf(buffer+n,sizeof buffer-n," %.2f %.2f %.2f %.2f",double(v[13]),double(v[14]),double(v[15]),double(v[16]));}
        if(select){const auto n=std::strlen(buffer);std::snprintf(buffer+n,sizeof buffer-n," 0x100");}
        if(count&&row==buffer){++count;return;}
        flush();row=buffer;count=1;
    }
    void flush(){if(count&&out.is_open()){out<<count<<' '<<row<<'\n';out.flush();}count=0;}
    void teleport(const std::vector<float>& v){
        flush();
        if(out.is_open()){out<<"teleport "<<v[0]<<' '<<v[1]<<' '<<v[2]<<' '<<v[3]<<'\n';out.flush();}
    }
    ~PilotRecorder(){flush();}
};

