    LoadoutFigure make_display_figure(std::unique_ptr<AnimatedCharacter> character,const AnimationGraphManifest& manifest,
                                      const AnimationClipBank& clips,const ActorMotionRegistry& registry,
                                      const std::vector<Texture>& images,const std::vector<bool>& textured,
                                      std::uint32_t slot_base,const char* ctor,
                                      std::shared_ptr<const omega::mods::CharacterModelOverrides> models){
        LoadoutFigure f;
        f.manifest=&manifest;f.clips=&clips;f.textured=textured;
        f.morph.expressions_enabled=false;
        if(images.size()!=character->parts().size()||textured.size()!=character->parts().size())
            throw std::runtime_error(std::string(ctor)+": the figure's part images differ from its parts");
        if(models&&models->lod0.size()!=character->parts().size())
            throw std::runtime_error(std::string(ctor)+": the figure's model replacements differ from its parts (132md3)");
        f.models=std::move(models);
        for(std::size_t i=0;i<images.size();++i){
            const auto slot=slot_base+static_cast<std::uint32_t>(i);
            f.slots.push_back(slot);
            if(textured[i])renderer.set_texture(slot,images[i]);
        }
        // 002c1100 / 0035d430 (0035db6c..0035db80): 18c6d0 / 18a710 with "DATA_ID_CasualStand" (004ac600): the
        // node name through the model's registry (004ffbc0, tag 0), installed with the default transition (0018a410).
        ActorMotionSelection stand;stand.tag=0;stand.name="DATA_ID_CasualStand";
        const auto reg=registry.resolve(stand);
        if(!reg.node)throw std::runtime_error(std::string(ctor)+": the player's motion set has no \"DATA_ID_CasualStand\" (004ac600)");
        auto request=make_motion_request(*reg.node,manifest.default_crossfade_duration);
        request.selector=reg.selector;
        character->play(request,MotionInstallMode::reset);
        character->apply_commands(actor_default_channel_commands());
        f.character=std::move(character);
        return f;
    }
    void set_loadout_figure(std::unique_ptr<AnimatedCharacter> character,const AnimationGraphManifest& manifest,
                            const AnimationClipBank& clips,const ActorMotionRegistry& registry,
                            const std::vector<Texture>& images,const std::vector<bool>& textured,
                            std::shared_ptr<const omega::mods::CharacterModelOverrides> models){
        figure=make_display_figure(std::move(character),manifest,clips,registry,images,textured,figure_slot_base,"002c1100",std::move(models));
    }
    void set_stats_figure(std::unique_ptr<AnimatedCharacter> character,const AnimationGraphManifest& manifest,
                          const AnimationClipBank& clips,const ActorMotionRegistry& registry,
                          const std::vector<Texture>& images,const std::vector<bool>& textured,
                          std::shared_ptr<const omega::mods::CharacterModelOverrides> models){
        stats_figure=make_display_figure(std::move(character),manifest,clips,registry,images,textured,stats_figure_slot_base,"0035d430",std::move(models));
    }
