    void upload(){
        if(zeus){
            for(auto it=zeus_uploaded.begin();it!=zeus_uploaded.end();){
                if(zeus->count(*it)){++it;continue;}
                renderer.drop_texture(*it);
                it=zeus_uploaded.erase(it);
            }
            for(const auto& [slot,image]:*zeus)if(zeus_uploaded.insert(slot).second)renderer.set_texture(slot,image);
        }
        if(uploaded==assets.images().size())return;
        for(const auto& [slot,image]:assets.images())renderer.set_texture(slot,image);
        uploaded=assets.images().size();
    }
