        if(!fs::is_regular_file("config/disc_us.json"))throw std::runtime_error("Run the sandbox from the repository root");

        std::ifstream tuning_stream(tuning_path);if(!tuning_stream)throw std::runtime_error("Cannot read tuning");
        const auto tuning=read_actor_animation_tuning(tuning_stream);
