            const auto r=frontend_app->run();
            if(!r.level){std::cout<<"Front end: ended without a level load ("<<r.frames<<" frames)\n";return 0;}
            // 00168438 loads G+140's level; the sandbox's level setup below stands in for it.
            if(*r.level!=mission)std::cout<<"Front end: --mission "<<mission<<" replaced by the front end's "<<*r.level<<"\n";
            mission=*r.level;
            std::cout<<"Front end: hand-off to the "<<mission<<" play setup\n";
            apply_mods_at_level_boundary(*frontend_app,mission);
            if(host_window)host_window->log_handoff("front end hand-off to "+mission+" (loading screen)");
