                if(has_lod1){lod_meshes.push_back(std::make_unique<SkinnedMesh>(look_mesh(mesh1?mesh1->archive:manskm_archive,mesh1?mesh1->name:part.mesh.members[1],lod1_bytes)));npc_lod1.push_back(lod_meshes.back().get());}
