            std::vector<const SkinnedMesh*> npc_lod1;std::vector<std::size_t> npc_pairs;   // LOD 1 meshes (null: LOD 0's), manifest pairs
            std::vector<std::string> model_keys,lod1_keys;   // 132md2 (port-only): the parts' model keys
            auto loaded=load_look_parts(look,label);
