        std::optional<std::size_t> coop_partner_record;std::int32_t coop_partner_node=-1;
        bool coop_partner_derived=false;   // Checkpoint 132ob10: the partner's roster entry is derived from record 0
        // Checkpoint 132pw3 (port-only, --coop-partners / coop_partners): partners 2 and 3, each derived from record 0 like
