                                const auto* e=p->effect_table->find(vision_fx_flare_indices[i]);
                                if(!e)throw std::runtime_error("00260a50: effect table entry "+std::to_string(vision_fx_flare_indices[i])+" is not loaded");
                                flares[i]=e->id;
