                                throw std::runtime_error("00260a50: the noise entry 0x21 is not a loaded SPECFX.HOG texture");
                            const auto bytes=disc.archive_member(fx_archive,p->effect_textures[n->id]);
                            if(bytes.size()<0x24)throw std::runtime_error("00260a50: "+p->effect_textures[n->id]+" has no TDX header");
                            const auto u16=[&bytes](std::size_t o){return static_cast<std::uint16_t>(bytes[o]|(bytes[o+1]<<8));};
                            vision_noise=VisionNoiseTexture{u16(4),u16(6),u16(0x22)};
                            vision_noise_image=decode_tdx(bytes);
