        struct NpcSectionSeen{std::uint32_t bits=0;std::int32_t health=0;std::int32_t item=-2;bool held=false;bool owner=false;bool seen=false;};
        std::map<std::uint32_t,NpcSectionSeen> lan_npc_seen;
