            if(const auto sp=spawned_npcs.find(static_cast<std::uint32_t>(actor));sp!=spawned_npcs.end())return sp->second.c;
            for(const auto& r:lan_remotes)if(!r.gone&&r.figure&&r.figure->actor==actor)return r.key;
            return 0;
