            for(const auto& [k,sp]:spawned_npcs)if(sp.c==key&&!actors.destroyed(k)&&actors.traversed(k))return std::size_t{k};
            for(const auto& r:lan_remotes)if(!r.gone&&r.figure&&r.key==key)return r.figure->actor;
