                                    const bool generated=spawned&&in_range(k);
                                    if(clear){
                                        if(k==0||!actors.actor(k).eligible()||std::find(c.wide.begin()+4,c.wide.end(),-static_cast<double>(combat_ids[k]))!=c.wide.end())continue;
                                        const auto p=actors.actor(k).published_position();
                                        if(std::hypot(p[0]-here.position[0],p[1]-here.position[1])>c.args[3]||std::abs(p[2]-here.position[2])>30.0F)continue;
                                    }
                                    else if(!generated&&std::find(c.wide.begin()+static_cast<std::ptrdiff_t>(first_id),c.wide.end(),static_cast<double>(combat_ids[k]))==c.wide.end())continue;
