                                        // sight (the lock needs it), head to head as clear; one out of sight only when none is in it.
                                        const auto from=actors.actor(0).skeleton_node_world_position(14),to=actors.actor(k).skeleton_node_world_position(14);
                                        const RootVector delta{to[0]-from[0],to[1]-from[1],to[2]-from[2],0};
                                        bool seen=true;
                                        if(const auto hit=trace_world_los(actors.actor(0).world(),{{from[0],from[1],from[2],1},delta,0,0x90})){
                                            const float reach=std::sqrt(delta[0]*delta[0]+delta[1]*delta[1]+delta[2]*delta[2]);
                                            seen=std::hypot(hit->point[0]-from[0],hit->point[1]-from[1],hit->point[2]-from[2])>=reach-1.0F;}
                                        if(!seen){if(unseen==actors.size()||d<best_unseen){unseen=k;best_unseen=d;}continue;}
