                gui_overlay_draw->draw(*state.renderer,static_cast<std::int32_t>(std::floor(gui_elapsed*1000.0)),dt,
                    game_screen_interact?&*game_screen_interact:nullptr,hud_object?&*hud_object:nullptr,frame,
                    gui_view?&*gui_view:nullptr,
                    PlayGunPreview{weapon_library.get(),gun_images_built?&gun_images:nullptr,actors.frame_counter(),
                        [&combat_session](std::uint32_t token)->const PickupMenuPreview*{
                            return combat_session?combat_session->pickup_menu_preview(token):nullptr;},mission});
                for(const auto& [i,colour]:held)hud_object->screen().text_object(i).colour=colour;
                // The text manager draw 003d0c10 (0x001690dc) after the render pass (see the step above).
