                if(a.frames==0)lines={"FRAME TIMES (MEASURING)"};
                else lines={"FRAME "+ms(a.total)+" MS  "+ms(a.fps)+" FPS  MAX "+ms(a.max_total),
                            "SIM "+ms(a.ms[FrameProfile::sim])+"  SCRIPT "+ms(a.ms[FrameProfile::script]),
                            "RENDER "+ms(a.ms[FrameProfile::render])+"  PRESENT "+ms(a.ms[FrameProfile::present])};
                const auto r=frame_rect(state.renderer->width(),state.renderer->height());
                const unsigned scale=FrameOverlay::scale_for(state.renderer->height());
                frame_overlay.draw(*state.renderer->device(),state.renderer->render_target(),
                    state.renderer->width(),state.renderer->height(),lines,r.x+4*scale,r.y+4*scale,scale);
                if(overlay_logged!=a.frames&&captures.count(frame)){
                    overlay_logged=a.frames;
                    std::cout<<"Frame overlay (port-only) at frame "<<frame<<":";for(const auto& t:lines)std::cout<<" ["<<t<<"]";std::cout<<"\n";
                }
