                    device_lost_inject(-1);
                    std::map<std::string,unsigned> sites;for(const auto& site:sweep_sites)++sites[site];
                    std::cout<<"Device-lost sweep (port-only diagnostic) complete at frame "<<frame<<": the device was lost at each of the "
                             <<*sweep_call<<" checked D3D calls of the frames from "<<sweep_first<<" in turn and recovered every time; calls:";
                    for(const auto& [site,n]:sites)std::cout<<" ["<<site<<"] x"<<n;
