                std::wostringstream title;title<<std::fixed<<std::setprecision(1)<<L"Omega sandbox | "<<std::wstring(mission.begin(),mission.end())
                    <<L" | pos "<<root.position[0]<<L", "<<root.position[1]<<L", "<<root.position[2]<<L" | heading "<<heading*57.29578F
                    <<L" | speed cmd "<<std::setprecision(2)<<sim.controls().speed<<L" | WASD/E/Q, P pause, O wire";
                window.set_title(title.str());
