        if(mission_host)std::cout<<"Mission scripts: "<<mission_host->calls().size()<<" native calls ("<<mission_host->deferred()
            <<" deferred), "<<mission_host->context().schedules().snapshot().size()<<" scheduled callbacks pending\n";
        if(mission_host&&mission_host->freed_ai_resends_skipped())
            std::cout<<"Freed-AI resend skip (port-only aid): "<<mission_host->freed_ai_resends_skipped()<<" calls skipped\n";
        if(mission_host&&mission_host->port_overlay_node_answers())
            std::cout<<"Co-op overlay nodes (port-only): "<<mission_host->port_overlay_node_answers()<<" node-native answers null (no script object)\n";
        if(mission_host&&mission_host->partner_objectives())
            for(const auto& a:mission_host->multiplayer_answers())
                std::cout<<"CPU partner (port-only): game::IsMultiplayer at "<<(a.module.empty()?"(no call site)":a.module+" "+a.function+" word "+std::to_string(a.word))
                         <<" = "<<(a.answer?1:0)<<"\n";
        if(sound_device){const auto s=sound_device->stats();
            std::cout<<"Sound output: "<<s.submitted_frames<<" frames queued to XAudio2 ("<<sound_device->latency_seconds()*1000<<" ms latency), "<<s.underruns
                <<" underruns ("<<s.silent_frames*1000/audio::Mixer::output_rate<<" ms of silence while the simulation was behind real time), "<<s.dropped_frames<<" frames dropped\n";
            if(s.losses)std::cout<<"Sound output (port-only): "<<s.losses<<" device losses, "<<s.reopens<<" re-opens ("<<s.failed_reopens<<" failed), "
                <<s.lost_frames<<" frames dropped while lost"<<(s.lost?"; lost at exit":"")<<"\n";}
